  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C10", "C19", "C20", "C21", "C35"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10", "C19", "C20", "C21", "C35"],
  "claims": [
    {
      "claim": "The closest supplied empirical contexts are PABA and PAS, which share the para-aminophenyl acidic motif with the query; PABA had F = 90.1 ± 8.7% in CF patients and was described as highly bioavailable, while PAS had F = 50–60% in humans.",
      "card_ids": ["C10", "C19", "C21"]
    },
    {
      "claim": "Additional PAS records show high absolute/relative bioavailability (118 ± 41% for sodium PAS capsules; 100% assumed for sodium PAS solution), reinforcing that the para-aminophenyl acid class is well absorbed orally despite ionization.",
      "card_ids": ["C20", "C35"]
    },
    {
      "claim": "No supplied record provides affirmative evidence that the query would have F < 20%; ionization at pH 7.4 is not a low-F signal because the analogous PABA/PAS acids are also ionized yet highly bioavailable.",
      "card_ids": ["C10", "C19", "C20", "C35"]
    },
    {
      "claim": "The L3 Cmax records (C38–C49) are oral exposure measurements for gliclazide, darunavir/amprenavir, procainamide, and M05; they lack matched IV comparators and are not threshold-relevant F measurements for the query, so they do not change the decision.",
      "card_ids": ["C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47", "C48", "C49"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47", "C48", "C49"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "No matched oral versus intravenous AUC data are available for the query.",
    "L3 Cmax records are for different molecules and lack IV comparators.",
    "No data address efflux, solubility-limited absorption, formulation, or food effects for the query.",
    "No data directly assess first-pass metabolism of the primary aromatic amine or the isoxazole ring."
  ],
  "decision_summary": "High: the closest transferable empirical contexts (PABA, PAS) show high oral bioavailability (90% and 50–60%, with additional PAS records at ~100–118%), the query is a small sulfanilamide-type analog, and no affirmative evidence supports F < 20%; L3 Cmax records are not direct F evidence and do not change the decision; confidence remains moderate because no direct query measurement exists."
}

